#!/usr/bin/env python
"""Ablation table for the field decoder of Opsis-S: every runs/abl_*_s<k> against the reference final_fov_s<k> (same seed),
overall and per family accuracy and NLL on the NuCLS test split and PanNuke accuracy; plus the 896 px state runs and the
slide tile budget runs when present.    python scripts/74_collect_ablations.py [--out results/collected/RESULTS_ablations.md]"""
import argparse, glob, json, os, re
import numpy as np, pandas as pd
from opsis import paths
from opsis.questions import FAMILY
ap = argparse.ArgumentParser(); ap.add_argument("--out", default=None); a = ap.parse_args(); R = paths.RUNS
def load(name):
    f = f"{R}/{name}/metrics_test.json"; return json.load(open(f)) if os.path.exists(f) else None
def summar(m):
    ops = m["per_op"]; n = sum(v["n"] for v in ops.values()); acc = sum(v["acc"] * v["n"] for v in ops.values()) / n
    fam = {}
    for f in ("cell", "region", "comp"):
        o = [v for k, v in ops.items() if FAMILY.get(k) == f]
        if o: fam[f] = sum(v["acc"] for v in o) / len(o)
    extra = m.get("per_op_extra"); pan = (sum(v["acc"] for v in extra.values()) / len(extra)) if extra else None
    return dict(nll=m["test_nll"], acc=acc, **{f"acc_{k}": v for k, v in fam.items()}, pannuke_acc=pan, cell_super=ops.get("cell_super", {}).get("acc"), cell_area_bin=ops.get("cell_area_bin", {}).get("acc"), compare_regions=ops.get("compare_regions", {}).get("acc"))
DESC = {"abl_noctx": "no context canvas", "abl_nopool": "no box pooled query tokens", "abl_nodens": "no density auxiliary loss", "abl_nopannuke": "NuCLS only (no PanNuke joint training)", "abl_primitives": "operator encoded by primitive tokens", "abl_small": "readout d=192, 1+1 layers", "abl_large": "readout d=768, 3+3 layers",
        "abl_compholdout": "compositional operators held out of training", "abl_fixed": "fixed multitask heads (no question conditioned attention)", "abl_qps8": "8 questions per state per step", "abl_qps128": "128 questions per state per step", "final_fov896": "896 px state (64 x 64 tokens, FOV at 0.125 mpp)"}
rows = []
for d in sorted(glob.glob(f"{R}/abl_*_s[0-9]") + glob.glob(f"{R}/final_fov896_s[0-9]")):
    name = os.path.basename(d); m = load(name)
    if not m: continue
    seed = int(name[-1]); ref = load(f"final_fov_s{seed}"); stem = re.sub(r"_s\d$", "", name)
    s = summar(m); r = summar(ref) if ref else {}
    rows.append(dict(run=name, change=DESC.get(stem, stem), **{k: s[k] for k in s}, **{f"d_{k}": (s[k] - r[k]) if (r.get(k) is not None and s.get(k) is not None) else None for k in ("nll", "acc", "pannuke_acc")}))
T = pd.DataFrame(rows)
if len(T):
    ref = summar(load("final_fov_s0")); print("reference final_fov_s0:", {k: (round(v, 3) if isinstance(v, float) else v) for k, v in ref.items()}); print(T.round(3).to_string(index=False))
sl = []
for d in sorted(glob.glob(f"{R}/abl_slide_k*_s[0-9]") + glob.glob(f"{R}/final_slide_pan_s0")):
    m = load(os.path.basename(d))
    if m: sl.append(dict(run=os.path.basename(d), k_tiles=m.get("k_tiles"), test_nll=m["test_nll"], **{op: m["per_op"][op]["acc"] for op in ("cancer_type", "pan_grade", "pan_necrosis", "pan_lvi", "pan_pni", "pan_precursor") if op in m["per_op"]}))
S = pd.DataFrame(sl)
if len(S): print(S.round(3).to_string(index=False))
if a.out:
    md = ["# Ablations (generated by scripts/74_collect_ablations.py)", "", "Opsis-S on fields, NuCLS test split, one factor changed from the reference final_fov (joint NuCLS + PanNuke, context, box pooling, density auxiliary, d = 384, 2 + 2 layers, 32 questions per state). d_ columns: difference to the reference run of the same seed.", ""]
    if len(T): md += ["| " + " | ".join(T.columns) + " |", "|" + "---|" * len(T.columns), *("| " + " | ".join("" if (isinstance(x, float) and np.isnan(x)) or x is None else (f"{x:.3f}" if isinstance(x, float) else str(x)) for x in r) + " |" for r in T.itertuples(index=False))]
    if len(S): md += ["", "## Opsis-S slide tile budget", "", "| " + " | ".join(S.columns) + " |", "|" + "---|" * len(S.columns), *("| " + " | ".join(f"{x:.3f}" if isinstance(x, float) else str(x) for x in r) + " |" for r in S.itertuples(index=False))]
    add = f"{paths.ROOT}/results/collected/RESULTS_ablations_addenda.md"; open(a.out, "w").write("\n".join(md) + "\n" + ("\n" + open(add).read() if os.path.exists(add) else "")); print("written", a.out)
